"""Progressive disclosure for purchase conditions; preserve saved evidence and actions."""
CSS='''
#po-study-state{margin:16px 0;padding:16px;border:1px solid #bfd2ed;border-radius:8px;background:#f3f7ff}#po-study-state h3{font-size:16px;margin:0 0 8px}#po-study-state p{font-size:13px;line-height:1.5}.po-state-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.po-state-tile{padding:12px;border-radius:8px;background:#edf1f6;border:1px solid #c5cfdd}.po-state-tile strong,.po-state-tile span{display:block}.po-state-tile strong{font-size:13px;margin-bottom:6px}.po-state-tile span{font-size:15px;font-weight:650}.po-state-tile[data-tone=green]{background:#e6f5eb;border-color:#8ec29d;color:#195d32}.po-state-tile[data-tone=amber]{background:#fff5dd;border-color:#d7b86c;color:#745000}.po-state-tile[data-tone=red]{background:#ffebe8;border-color:#d9948d;color:#8b2922}.po-state-tile span::before{content:'●';margin-right:7px}#po-study-state details>summary,.po-cash>details>summary{cursor:pointer;font-weight:bold;font-size:14px}.po-cash{background:#f4f8ff;border:1px solid #bfd2ed}.po-state-reference{color:#49617b}#po-study-state #po-save-progress{margin:0;padding:0;border:0}#po-study-state .po-user-tasks button{white-space:normal}@media(max-width:650px){.po-state-grid{grid-template-columns:1fr}}
'''
JS=r'''
(function(){
 const host=document.createElement('section');host.id='po-study-state';host.setAttribute('aria-live','polite');$('po-purchase-summary').before(host);let savedMode=false;
 function p(box,text){const el=document.createElement('p');el.textContent=text;box.append(el)}
 function tile(grid,label,text,tone){const box=document.createElement('div');box.className='po-state-tile';box.dataset.tone=tone;const h=document.createElement('strong'),v=document.createElement('span');h.textContent=label;v.textContent=text;box.append(h,v);grid.append(box)}
 function draft(r){host.replaceChildren();host.dataset.mode='draft';const h=document.createElement('h3');h.textContent='ESTADO DEL ESTUDIO · BORRADOR';host.append(h);const grid=document.createElement('div');grid.className='po-state-grid';tile(grid,'GUARDADO','Sin guardar','amber');tile(grid,'DINERO PREVISTO',r?.status==='SHORTFALL'?'Falta dinero':r?.status==='WITHIN_DECLARED_SCENARIO'?'Hay margen':'Pendiente de calcular',r?.status==='SHORTFALL'?'red':r?.status==='WITHIN_DECLARED_SCENARIO'?'green':'amber');tile(grid,'COMPRA','Sin confirmar','amber');host.append(grid);p(host,'Cambiar datos no guarda el estudio ni confirma un pedido.');}
 const oldSummary=renderPurchaseSummary;renderPurchaseSummary=function(box,r,editable){if(editable){if(savedMode)return;draft(r)}oldSummary(box,r,editable)};
 const oldClear=clearPurchaseSummary;clearPurchaseSummary=function(){savedMode=false;draft(null);oldClear()};
 const oldFinance=renderFinancialContext;renderFinancialContext=function(report){oldFinance(report);savedMode=true;host.replaceChildren();host.dataset.mode='saved';const proposal=report.proposal||{},cash=proposal.cash_orientation_at_save,overview=$('po-save-progress');const h=document.createElement('h3');h.textContent='ESTADO DEL ESTUDIO GUARDADO';host.append(h);p(host,(proposal.reference||report.reference||'Estudio guardado')+' · Resultado conservado. El formulario de arriba no cambia al consultar este estudio.');const grid=document.createElement('div');grid.className='po-state-grid';tile(grid,'GUARDADO','Guardado correctamente','green');tile(grid,'DINERO PREVISTO',cash?.status==='SHORTFALL'?'Falta dinero':cash?.status==='WITHIN_DECLARED_SCENARIO'?'Hay margen':'Faltan datos',cash?.status==='SHORTFALL'?'red':cash?.status==='WITHIN_DECLARED_SCENARIO'?'green':'amber');const conflict=Number(report.payment_documentary_review?.conflict_count)>0||report.payment_associations?.declared_calendar_coverage?.status==='CONFLICTING_DECLARATIONS';tile(grid,'COMPROBACIONES',conflict?'Hay datos en conflicto':'Por revisar',conflict?'red':'amber');host.append(grid);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Saber más · estado y acciones pendientes';details.append(summary);if(overview){overview.querySelector('h3')?.remove();details.append(overview)}host.append(details);const back=document.createElement('button');back.type='button';back.id='po-return-draft';back.textContent='Volver al borrador';back.onclick=()=>{savedMode=false;clearPurchaseSummary();schedulePurchaseCash()};host.append(back);const holder=document.createElement('div');renderSavedPurchaseAlternativesTable(holder,cash);const savedTable=holder.firstElementChild;$('po-alternatives-table').replaceChildren(...Array.from(savedTable.childNodes));$('po-alternatives-table').dataset.mode='saved';if(typeof showSavedPrimaryPurchaseSummary==='function')showSavedPrimaryPurchaseSummary(cash);};
 // Leave the chart and short financial verdict visible; preserve all controls in a disclosure.
 const oldCash=renderPurchaseCash;renderPurchaseCash=function(box,r,editable){oldCash(box,r,editable);const keep=Array.from(box.children).slice(0,2);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Saber más · stock, pagos y comprobaciones';details.append(summary);for(const child of Array.from(box.children)){if(keep.includes(child)||child.matches('.po-treasury-chart'))continue;details.append(child)}box.append(details);};
 const oldAlternatives=renderPurchaseAlternativesTable;renderPurchaseAlternativesTable=function(r){if(savedMode)return;oldAlternatives(r);$('po-alternatives-table').dataset.mode='draft'};
 $('dataset').addEventListener('change',()=>{savedMode=false;draft(null)});draft(null);
})();
'''
